-- Forward repair: hiding a core claim alone cannot make its unsafe owner public.
SET LOCAL ROLE start_catalog_owner;
SET LOCAL search_path=pg_catalog,start_catalog,pg_temp;
CREATE OR REPLACE FUNCTION start_catalog.place_public(key uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,start_catalog,pg_temp AS $$
 SELECT EXISTS(SELECT FROM place p WHERE p.id=key AND publication='published' AND review='approved' AND visibility='public' AND NOT EXISTS(SELECT FROM claim c WHERE c.place_id=p.id AND c.is_core AND NOT claim_public(c.id))) $$;
CREATE OR REPLACE FUNCTION start_catalog.relation_public(key uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,start_catalog,pg_temp AS $$ SELECT EXISTS(SELECT FROM artist_place_relation r WHERE r.id=key AND artist_public(r.artist_id) AND place_public(r.place_id) AND r.review='approved' AND r.visibility='public' AND NOT r.severe_dispute AND r.credible_basis AND NOT EXISTS(SELECT FROM claim c WHERE c.relation_id=r.id AND c.is_core AND NOT claim_public(c.id)) AND
 ((r.verification='verified' AND (EXISTS(SELECT FROM relation_evidence e WHERE e.relation_id=r.id AND source_public(e.evidence_source_id)) OR EXISTS(SELECT FROM claim c WHERE c.relation_id=r.id AND claim_public(c.id)))) OR
 (r.verification IN ('unverified','partial') AND length(trim(coalesce(r.public_caveat,'')))>0))) $$;
CREATE FUNCTION start_catalog.event_public(key uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,start_catalog,pg_temp AS $$
 SELECT EXISTS(SELECT FROM event e WHERE e.id=key AND e.publication='published' AND e.review='approved' AND e.visibility='public' AND place_public(e.place_id) AND NOT EXISTS(SELECT FROM claim c WHERE c.event_id=e.id AND c.is_core AND NOT claim_public(c.id))) $$;
CREATE OR REPLACE VIEW start_public.events WITH (security_barrier=true) AS SELECT e.id,e.title AS name,e.normalized_title AS normalized_name,(SELECT coalesce(array_agg(a.artist_id ORDER BY a.artist_id),'{}') FROM event_artist a WHERE a.event_id=e.id AND artist_public(a.artist_id)) AS artist_ids,ARRAY[p.city_id]::uuid[] AS city_ids,ARRAY[p.id]::uuid[] AS place_ids,jsonb_build_object('type','event','id',e.id,'title',e.title,'artists',coalesce((SELECT jsonb_agg(artist_json(a.artist_id) ORDER BY a.artist_id) FROM event_artist a WHERE a.event_id=e.id AND artist_public(a.artist_id)),'[]'),'startsAt',to_char(e.starts_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'endsAt',CASE WHEN e.ends_at IS NOT NULL THEN to_char(e.ends_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,'venue',jsonb_build_object('id',p.id,'name',p.name),'city',city_json(p.city_id),'state',e.status,'publication',e.publication,'verification',e.verification,'hero',media_json(e.hero_media_id),'matchedReasons','[]'::jsonb) AS data,owner_claims('event',e.id) AS claims,owner_sources('event',e.id) AS sources FROM event e JOIN place p ON p.id=e.place_id WHERE event_public(e.id);
REVOKE ALL ON FUNCTION start_catalog.event_public(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION start_catalog.event_public(uuid) TO start_public_reader;
RESET ROLE;
